"""Policy engine with first_match and collect_all evaluation modes."""
from __future__ import annotations

import yaml
from pathlib import Path


class PolicyError(ValueError):
    """Raised when the ruleset is invalid."""


class Rule:
    __slots__ = ("id", "priority", "when", "then")

    def __init__(self, rule_id: str, priority: int, when: dict, then: str):
        if then not in ("allow", "deny", "flag"):
            raise PolicyError(f"rule {rule_id!r}: invalid verdict {then!r}")
        self.id = rule_id
        self.priority = int(priority)
        self.when = dict(when)
        self.then = then

    def matches(self, input_: dict) -> bool:
        return all(
            k in input_ and input_[k] == expected for k, expected in self.when.items()
        )


def load_rules(path: str | Path) -> list[Rule]:
    with open(path) as f:
        raw = yaml.safe_load(f) or []
    if not isinstance(raw, list):
        raise PolicyError("rules.yaml must contain a list of rules")
    rules = [
        Rule(
            rule_id=r["id"],
            priority=r["priority"],
            when=r.get("when") or {},
            then=r["then"],
        )
        for r in raw
    ]
    ids = [r.id for r in rules]
    dupes = {i for i in ids if ids.count(i) > 1}
    if dupes:
        raise PolicyError(f"duplicate rule ids: {sorted(dupes)}")
    return rules


# Precedence for collect_all combined outcome.
_VERDICT_RANK = {"deny": 3, "allow": 2, "flag": 1}


def _combined(verdicts: list[str]) -> str:
    return max(verdicts, key=lambda v: _VERDICT_RANK[v])


def evaluate(input_: dict, mode: str, rules_path: str | Path = "rules.yaml") -> dict:
    """Evaluate `input_` against the ruleset in the given mode.

    mode="first_match": highest-priority matching rule wins; ties broken by
        file order. No match -> outcome "flag", fired [].
    mode="collect_all": every matching rule fires; combined outcome is deny
        > allow > flag. No match -> outcome "flag", fired [].
    """
    if mode not in ("first_match", "collect_all"):
        raise PolicyError(f"unknown mode {mode!r}")
    rules = load_rules(rules_path)
    matching = [r for r in rules if r.matches(input_)]

    if not matching:
        return {"outcome": "flag", "fired": []}

    if mode == "first_match":
        winner = max(matching, key=rules.index)  # priority, file-order tie-break
        return {"outcome": winner.then, "fired": [winner.id]}

    fired = [r.id for r in matching]
    return {
        "outcome": _combined([r.then for r in matching]),
        "fired": fired,
    }

